import{m as e}from"./merge-BmcoofH2.js";const r={"unternehmer-firma-firmenbuch":[{de:{term:"Firmenkern & Firmenzusatz",erklaerung:"Die Firma besteht aus dem frei wählbaren Firmenkern und dem Firmenzusatz, der die Rechtsform zeigt (e. U., OG, KG, GmbH, AG).",beispiel:"„Red Bull“ (Kern) + „GmbH“ (Zusatz)"},en:{term:"Core name & legal-form suffix",erklaerung:"A company name consists of the freely chosen core name and a suffix that shows the legal form (e. U., OG, KG, GmbH, AG).",beispiel:"‘Red Bull’ (core) + ‘GmbH’ (suffix)"},hu:{term:"Cégnévmag és cégforma-toldat",erklaerung:"A cégnév a szabadon választható cégnévmagból és a jogi formát jelző toldatból áll (e. U., OG, KG, GmbH, AG).",beispiel:"„Red Bull” (mag) + „GmbH” (toldat)"}},{de:{term:"Firmenarten",erklaerung:"Personenfirma (Name des Inhabers), Sachfirma (Hinweis auf den Gegenstand), Fantasiefirma (erfundener Name), gemischte Firma (Kombination).",beispiel:"Thomas Radler e. U. · Österreichische Post AG · Red Bull GmbH · Max Steindl Immobilien OG"},en:{term:"Types of company names",erklaerung:"Personal name (owner's name), descriptive name (refers to the activity), fantasy name (invented), mixed name (combination).",beispiel:"Thomas Radler e. U. · Österreichische Post AG · Red Bull GmbH · Max Steindl Immobilien OG"},hu:{term:"Cégnévtípusok",erklaerung:"Személynév-cégnév (a tulajdonos neve), tárgyi cégnév (utal a tevékenységre), fantázianév (kitalált név), vegyes cégnév (kombináció).",beispiel:"Thomas Radler e. U. · Österreichische Post AG · Red Bull GmbH · Max Steindl Immobilien OG"}},{de:{term:"Grundsätze der Firmenbildung",erklaerung:"Kennzeichnungseignung (lesbar, aussprechbar), Unterscheidungskraft (klar anders als Firmen am selben Ort), Irreführungsverbot (keine falschen Angaben).",beispiel:"Kein „KFZ“ im Namen, wenn nur Motorräder verkauft werden"},en:{term:"Rules for company names",erklaerung:"Suitability as a name (readable, pronounceable), distinctiveness (clearly different from firms in the same place), no misleading information.",beispiel:"No ‘car’ in the name if only motorbikes are sold"},hu:{term:"A cégnévképzés elvei",erklaerung:"Megjelölésre való alkalmasság (olvasható, kimondható), megkülönböztető képesség (eltér az azonos helyen lévő cégektől), megtévesztés tilalma.",beispiel:"Ne legyen „autó” a névben, ha csak motorokat árulnak"}},{de:{term:"Hauptbuch vs. Urkundensammlung",erklaerung:"Das Hauptbuch enthält die Daten (Firmenname, FN, Rechtsform, Sitz, Inhaber). Die Urkundensammlung enthält Dokumente (Gesellschaftsvertrag, Musterunterschriften, Bilanz)."},en:{term:"Main register vs. collection of documents",erklaerung:"The main register holds the data (name, register number, legal form, seat, owners). The collection of documents holds documents (partnership agreement, specimen signatures, balance sheet)."},hu:{term:"Főkönyv és okirattár",erklaerung:"A főkönyv az adatokat tartalmazza (cégnév, cégjegyzékszám, jogi forma, székhely, tulajdonos). Az okirattár a dokumentumokat (társasági szerződés, aláírásminták, mérleg)."}},{de:{term:"Unternehmensbezeichnung",erklaerung:"Name eines Unternehmens, das NICHT im Firmenbuch eingetragen ist. Nur eingetragene Unternehmen führen eine Firma.",beispiel:"Ein kleines, nicht eingetragenes Nagelstudio „Nails by Lena“"},en:{term:"Business designation",erklaerung:"The name of a business that is NOT entered in the company register. Only registered businesses have a company name (Firma) in the legal sense.",beispiel:"A small unregistered nail studio ‘Nails by Lena’"},hu:{term:"Vállalkozásmegjelölés",erklaerung:"Egy cégjegyzékbe NEM bejegyzett vállalkozás neve. Jogi értelemben vett cégneve csak a bejegyzett vállalkozásnak van.",beispiel:"Egy kis, be nem jegyzett körömszalon: „Nails by Lena”"}}],"rechtsformen-unternehmen":[{de:{term:"Komplementär vs. Kommanditist",erklaerung:"Komplementär = Vollhafter der KG, leitet und vertritt. Kommanditist = Teilhafter, haftet nur bis zur Haftsumme, hat nur ein Kontrollrecht."},en:{term:"General partner vs. limited partner",erklaerung:"General partner = fully liable partner of a KG who manages and represents it. Limited partner = liable only up to the liability amount, with only a right of control."},hu:{term:"Beltag és kültag",erklaerung:"Beltag = a KG korlátlanul felelős tagja, vezeti és képviseli a társaságot. Kültag = csak a vállalt összegig felel, csak ellenőrzési joga van."}},{de:{term:"Solidarische & unmittelbare Haftung",erklaerung:"Solidarisch: Jeder Gesellschafter haftet für ALLE Schulden, der Gläubiger wählt aus. Unmittelbar: Der Gläubiger kann sofort den Gesellschafter selbst belangen.",beispiel:"OG mit 3 Gesellschaftern: Gläubiger verlangt alle 60.000 € von einem"},en:{term:"Joint and several & direct liability",erklaerung:"Joint and several: each partner is liable for ALL debts, the creditor chooses whom to claim from. Direct: the creditor can go straight to the partner personally.",beispiel:"OG with 3 partners: creditor claims all €60,000 from one"},hu:{term:"Egyetemleges és közvetlen felelősség",erklaerung:"Egyetemleges: minden tag felel az ÖSSZES tartozásért, a hitelező választ. Közvetlen: a hitelező azonnal magát a tagot veheti igénybe.",beispiel:"Háromtagú OG: a hitelező mind a 60 000 €-t egy tagtól követeli"}},{de:{term:"GmbH & Co KG",erklaerung:"KG, bei der eine GmbH Komplementär ist. Die GmbH haftet nur mit ihrem Vermögen – so haftet keine natürliche Person unbeschränkt mit Privatvermögen."},en:{term:"GmbH & Co KG",erklaerung:"A KG whose general partner is a GmbH. The GmbH is liable only with its own assets – so no natural person is personally liable without limit."},hu:{term:"GmbH & Co KG",erklaerung:"Olyan betéti társaság, amelynek beltagja egy kft. A kft. csak a saját vagyonával felel – így egyetlen természetes személy sem felel korlátlanul a magánvagyonával."}},{de:{term:"Steuerbelastung Kapitalgesellschaft",erklaerung:"Die Gesellschaft zahlt 23 % KöSt auf den Gewinn; auf Ausschüttungen zahlen Gesellschafter zusätzlich 27,5 % KESt. Gesamt ≈ 44,175 %.",beispiel:"100 € Gewinn − 23 € KöSt = 77 € · 27,5 % = 21,175 € KESt"},en:{term:"Tax burden of a corporation",erklaerung:"The company pays 23% corporation tax on profit; shareholders also pay 27.5% capital gains tax (KESt) on distributions. Total ≈ 44.175%.",beispiel:"€100 profit − €23 corporation tax = €77 · 27.5% = €21.175 KESt"},hu:{term:"A tőketársaság adóterhe",erklaerung:"A társaság a nyereség után 23% társasági adót fizet; a kifizetések után a tagok még 27,5% tőkehozam-adót (KESt). Összesen ≈ 44,175%.",beispiel:"100 € nyereség − 23 € társasági adó = 77 € · 27,5% = 21,175 € KESt"}},{de:{term:"Generalversammlung vs. Hauptversammlung",erklaerung:"Generalversammlung = Versammlung der GmbH-Gesellschafter (Stimmrecht nach Stammeinlage). Hauptversammlung = Versammlung der Aktionär:innen einer AG. Beide mind. 1× pro Jahr."},en:{term:"General meeting (GmbH) vs. shareholders' meeting (AG)",erklaerung:"Generalversammlung = meeting of GmbH shareholders (votes according to capital contribution). Hauptversammlung = meeting of an AG's shareholders. Both at least once a year."},hu:{term:"Taggyűlés és közgyűlés",erklaerung:"Taggyűlés = a kft. tagjainak gyűlése (szavazati jog a törzsbetét szerint). Közgyűlés = az rt. részvényeseinek gyűlése. Mindkettő legalább évente egyszer."}}],vollmachten:[{de:{term:"Gesamtprokura",erklaerung:"Der Prokurist darf nur gemeinsam mit einem oder mehreren anderen Prokuristen handeln (Vier-Augen-Prinzip). Gemischte Prokura: nur gemeinsam mit Geschäftsführer/Vorstand."},en:{term:"Joint Prokura",erklaerung:"The Prokurist may only act together with one or more other Prokuristen (four-eyes principle). Mixed Prokura: only together with a managing director/board member."},hu:{term:"Együttes prokúra",erklaerung:"A prokurista csak egy vagy több másik prokuristával együtt járhat el (négy szem elve). Vegyes prokúra: csak ügyvezetővel/igazgatósági taggal együtt."}},{de:{term:"Generalvollmacht",erklaerung:"Handlungsvollmacht für alle gewöhnlichen Geschäfte des Unternehmens. Unterschrift mit „i. V.“ (in Vertretung).",beispiel:"Filialleiterin wählt die Kollektion aus und stellt Personal ein"},en:{term:"General power of attorney",erklaerung:"Commercial power of attorney for all ordinary transactions of the business. Signature with ‘i. V.’ (in Vertretung – as representative).",beispiel:"Branch manager chooses the collection and hires staff"},hu:{term:"Általános meghatalmazás",erklaerung:"Kereskedelmi meghatalmazás a vállalkozás minden szokásos ügyletére. Aláírás „i. V.” toldattal (in Vertretung – képviseletben).",beispiel:"Az üzletvezetőnő kiválasztja a kollekciót és munkatársakat vesz fel"}},{de:{term:"Art- und Spezialvollmacht",erklaerung:"Artvollmacht: für eine bestimmte Art von Geschäften. Spezialvollmacht: für eine einzelne Handlung. Beide unterschreiben mit „i. A.“ (im Auftrag).",beispiel:"Warenbestellung bis 40.000 € (Art) · einen Spiegel kaufen (Spezial)"},en:{term:"Power for a type of deal & special power",erklaerung:"Power for a type of deal: for one kind of transaction. Special power: for a single act. Both sign with ‘i. A.’ (im Auftrag – on behalf of).",beispiel:"Ordering goods up to €40,000 (type) · buying a mirror (special)"},hu:{term:"Ügyfajtára szóló és eseti meghatalmazás",erklaerung:"Ügyfajtára szóló: egy bizonyos ügyletfajtára. Eseti: egyetlen cselekményre. Mindkettő „i. A.” toldattal ír alá (im Auftrag – megbízásból).",beispiel:"Árurendelés 40 000 €-ig (ügyfajta) · egy tükör megvásárlása (eseti)"}},{de:{term:"Schlüssiges Handeln",erklaerung:"Eine Vollmacht entsteht durch Verhalten statt durch ausdrückliche Erklärung. Möglich bei der Handlungsvollmacht, nicht bei der Prokura.",beispiel:"Mitarbeiter bestellt zum 4. Mal Kaffeebohnen, der Chef zahlt jedes Mal"},en:{term:"Authority by conduct",erklaerung:"A power of attorney arises from behaviour instead of an express declaration. Possible for a commercial power of attorney, not for Prokura.",beispiel:"An employee orders coffee beans for the 4th time and the boss pays every time"},hu:{term:"Ráutaló magatartás",erklaerung:"A meghatalmazás kifejezett nyilatkozat helyett magatartással jön létre. Kereskedelmi meghatalmazásnál lehetséges, prokúránál nem.",beispiel:"Egy munkatárs negyedszer rendel kávébabot, és a főnök minden alkalommal fizet"}},{de:{term:"Interne Beschränkung",erklaerung:"Prokura: gilt nicht gegenüber Dritten, der Vertrag bleibt gültig. Handlungsvollmacht: gilt auch gegenüber Dritten, wenn sie davon wissen (müssten)."},en:{term:"Internal restriction",erklaerung:"Prokura: not effective against third parties, the contract stays valid. Commercial power of attorney: also effective against third parties who know (or should know) of it."},hu:{term:"Belső korlátozás",erklaerung:"Prokúra: harmadik személyekkel szemben nem hatályos, a szerződés érvényes marad. Kereskedelmi meghatalmazás: harmadik féllel szemben is hatályos, ha tud(nia kellene) róla."}}],beschaeftigungsverhaeltnisse:[{de:{term:"Persönliche Abhängigkeit",erklaerung:"Kernmerkmal des echten Arbeitsvertrags: Bindung an Weisungen, Arbeitszeit und Arbeitsort, persönliche Arbeitspflicht ohne Vertretung."},en:{term:"Personal dependence",erklaerung:"Key feature of a ‘real’ employment contract: bound by instructions, working hours and place of work, personal duty to work without substitution."},hu:{term:"Személyes függőség",erklaerung:"A „valódi” munkaszerződés fő ismérve: kötöttség az utasításokhoz, a munkaidőhöz és a munkavégzés helyéhez, személyes munkavégzési kötelezettség helyettesítés nélkül."}},{de:{term:"ÖGK vs. SVS",erklaerung:"ÖGK (Österreichische Gesundheitskasse): Arbeitgeber meldet echte und freie Dienstnehmer:innen an. SVS: hier versichern sich Selbstständige und Werkvertragsnehmer:innen selbst."},en:{term:"ÖGK vs. SVS",erklaerung:"ÖGK (Austrian Health Insurance Fund): the employer registers employees and freelance workers. SVS: where the self-employed and contractors insure themselves."},hu:{term:"ÖGK és SVS",erklaerung:"ÖGK (Osztrák Egészségpénztár): a munkáltató ide jelenti be a munkavállalókat és a szabad szolgálati szerződéssel dolgozókat. SVS: az önállók és a vállalkozók itt biztosítják magukat."}},{de:{term:"Sonderzahlungen",erklaerung:"Urlaubs- und Weihnachtsgeld (13. und 14. Gehalt). Anspruch haben echte Arbeitnehmer:innen – auch geringfügig Beschäftigte –, nicht aber freie Dienstnehmer:innen und Werkvertragsnehmer:innen."},en:{term:"Special payments",erklaerung:"Holiday and Christmas bonus (13th and 14th salary). Employees – including marginal employees – are entitled to them, but freelance workers and contractors are not."},hu:{term:"Különjuttatások",erklaerung:"Szabadság- és karácsonyi pénz (13. és 14. havi fizetés). A munkavállalóknak – a csekély mértékben foglalkoztatottaknak is – jár, a szabad szolgálati szerződéssel dolgozóknak és a vállalkozóknak nem."}},{de:{term:"Entgeltfortzahlung",erklaerung:"Der Arbeitgeber zahlt das Entgelt im Krankenstand für eine bestimmte Zeit weiter. Gilt beim echten Arbeitsvertrag, nicht beim freien Dienst- oder Werkvertrag."},en:{term:"Continued pay during sick leave",erklaerung:"The employer continues to pay wages during sick leave for a certain period. Applies to ‘real’ employment contracts, not to freelance service contracts or contracts for work."},hu:{term:"Betegszabadság alatti bérfolyósítás",erklaerung:"A munkáltató betegség esetén egy bizonyos ideig tovább fizeti a bért. A „valódi” munkaszerződésnél jár, a szabad szolgálati és a vállalkozási szerződésnél nem."}},{de:{term:"Gewährleistung beim Werkvertrag",erklaerung:"Weil ein Erfolg geschuldet ist, haftet der Werkvertragsnehmer für Mängel am Werk und muss z. B. nachbessern. Entgelt gibt es nur für das vertragsgemäße Werk.",beispiel:"Malerin muss Risse in der frisch gestrichenen Wand beheben"},en:{term:"Warranty under a contract for work",erklaerung:"Because a result is owed, the contractor is liable for defects in the work and must e.g. repair them. Payment is only due for work done as agreed.",beispiel:"A painter has to fix cracks in the freshly painted wall"},hu:{term:"Szavatosság vállalkozási szerződésnél",erklaerung:"Mivel eredménnyel tartozik, a vállalkozó felel a mű hibáiért, és pl. javítania kell. Díjazás csak a szerződésszerű műért jár.",beispiel:"A festőnőnek ki kell javítania a frissen festett fal repedéseit"}},{de:{term:"Lohnsteuer vs. Einkommensteuererklärung",erklaerung:"Beim echten Arbeitsvertrag zieht der Arbeitgeber die Lohnsteuer ab und führt sie ab. Freie Dienst- und Werkvertragsnehmer:innen versteuern selbst per Einkommensteuererklärung."},en:{term:"Wage tax vs. income tax return",erklaerung:"Under a ‘real’ employment contract the employer deducts and pays the wage tax. Freelance workers and contractors pay tax themselves via an income tax return."},hu:{term:"Béradó és jövedelemadó-bevallás",erklaerung:"A „valódi” munkaszerződésnél a munkáltató vonja le és fizeti be a béradót. A szabad szolgálati szerződéssel dolgozók és a vállalkozók maguk adóznak jövedelemadó-bevallással."}},{de:{term:"Tatsächliche Verhältnisse zählen",erklaerung:"Ob ein echter, freier Dienst- oder Werkvertrag vorliegt, entscheidet die tatsächliche Gestaltung der Arbeit – nicht die Bezeichnung im Vertrag.",beispiel:"„Freier Dienstvertrag“, aber fixe Zeiten und Weisungen → echter Arbeitsvertrag"},en:{term:"Actual circumstances count",erklaerung:"Whether there is a ‘real’ employment, freelance or work contract depends on how the work is actually organised – not on the label in the contract.",beispiel:"‘Freelance contract’, but fixed hours and instructions → real employment contract"},hu:{term:"A tényleges viszonyok számítanak",erklaerung:"Az, hogy valódi munkaszerződésről, szabad szolgálati vagy vállalkozási szerződésről van-e szó, a munka tényleges megszervezésén múlik – nem a szerződésbeli megnevezésen.",beispiel:"„Szabad szolgálati szerződés”, de kötött munkaidő és utasítások → valódi munkaszerződés"}}],"kaufvertraege-aussenhandel":[{de:{term:"Einpunkt- vs. Zweipunktklausel",erklaerung:"E-, F- und D-Klauseln: Risiko und Kosten gehen am selben Ort über. C-Klauseln: Risiko geht früh beim Frachtführer über, Kosten trägt der Verkäufer bis zum Bestimmungsort.",beispiel:"CPT Graz: Risiko in München, Kosten bis Graz"},en:{term:"One-point vs. two-point clause",erklaerung:"E, F and D clauses: risk and costs pass at the same place. C clauses: risk passes early at the carrier, while the seller pays the costs up to the destination.",beispiel:"CPT Graz: risk in Munich, costs up to Graz"},hu:{term:"Egypontos és kétpontos klauzula",erklaerung:"E-, F- és D-klauzulák: a kockázat és a költség ugyanott száll át. C-klauzulák: a kockázat korán, a fuvarozónál száll át, a költséget az eladó a rendeltetési helyig viseli.",beispiel:"CPT Graz: kockázat Münchenben, költség Grazig"}},{de:{term:"Pro-Forma-Rechnung vs. Handelsrechnung",erklaerung:"Pro-Forma-Rechnung: vor der Lieferung, keine Zahlungspflicht, für Zoll/Importgenehmigung. Handelsrechnung (Faktura): bestätigt den tatsächlichen Verkauf."},en:{term:"Pro forma invoice vs. commercial invoice",erklaerung:"Pro forma invoice: issued before delivery, no obligation to pay, used for customs/import licences. Commercial invoice: confirms the actual sale."},hu:{term:"Proforma számla és kereskedelmi számla",erklaerung:"Proforma számla: a szállítás előtt, fizetési kötelezettség nélkül, vámhoz/behozatali engedélyhez. Kereskedelmi számla: a tényleges eladást igazolja."}},{de:{term:"Ursprungszeugnis & Warenverkehrsbescheinigung",erklaerung:"Ursprungszeugnis: beweist, aus welchem Land die Ware stammt. Warenverkehrsbescheinigung: ermöglicht Zollfreiheit oder begünstigte Zölle bei Freihandelsabkommen."},en:{term:"Certificate of origin & movement certificate",erklaerung:"Certificate of origin: proves which country the goods come from. Movement certificate: allows duty-free or preferential customs treatment under free trade agreements."},hu:{term:"Származási bizonyítvány és szállítási bizonyítvány",erklaerung:"Származási bizonyítvány: igazolja, melyik országból származik az áru. Szállítási bizonyítvány (EUR.1): vámmentességet vagy kedvezményes vámot tesz lehetővé szabadkereskedelmi megállapodás alapján."}},{de:{term:"Bestätigtes vs. unbestätigtes Akkreditiv",erklaerung:"Unbestätigt: Nur die Bank des Käufers haftet für die Zahlung. Bestätigt: Zusätzlich haftet die Bank des Verkäufers – noch mehr Sicherheit für den Exporteur."},en:{term:"Confirmed vs. unconfirmed letter of credit",erklaerung:"Unconfirmed: only the buyer's bank is liable for payment. Confirmed: the seller's bank is also liable – even more security for the exporter."},hu:{term:"Megerősített és meg nem erősített akkreditív",erklaerung:"Meg nem erősített: csak a vevő bankja felel a fizetésért. Megerősített: az eladó bankja is felel – még nagyobb biztonság az exportőrnek."}},{de:{term:"Pönale",erklaerung:"Vertragsstrafe, die der Lieferant zahlen muss, wenn er z. B. zu spät liefert. Schützt den Importeur vor dem Lieferrisiko.",beispiel:"500 € pro Tag Lieferverzug"},en:{term:"Contractual penalty",erklaerung:"A penalty the supplier must pay if, for example, he delivers late. Protects the importer against delivery risk.",beispiel:"€500 per day of late delivery"},hu:{term:"Kötbér",erklaerung:"Szerződéses büntetés, amelyet a szállítónak fizetnie kell, ha pl. késve szállít. Az importőrt védi a szállítási kockázattal szemben.",beispiel:"Késedelmes szállítás esetén napi 500 €"}}],"grundlagen-leistungserstellung-2jg":[{de:{term:"Produktivität",erklaerung:"Mengenmäßiger Output / mengenmäßiger Input. Misst nur Mengen (Stück, kg, Stunden), keine Euro-Werte.",beispiel:"200 Teile / 4 Maschinenstunden = 50 Teile pro Stunde"},en:{term:"Productivity",erklaerung:"Quantity of output / quantity of input. Measures only quantities (units, kg, hours), not euro values.",beispiel:"200 parts / 4 machine hours = 50 parts per hour"},hu:{term:"Termelékenység",erklaerung:"Mennyiségi output / mennyiségi input. Csak mennyiségeket mér (darab, kg, óra), euróértékeket nem.",beispiel:"200 alkatrész / 4 gépóra = óránként 50 alkatrész"}},{de:{term:"Wirtschaftlichkeit",erklaerung:"Erlöse / Kosten. Über 1 = Gewinn, genau 1 = kostendeckend, unter 1 = Verlust.",beispiel:"18.000 € / 15.000 € = 1,2 → Gewinn"},en:{term:"Economic efficiency",erklaerung:"Revenue / costs. Above 1 = profit, exactly 1 = break-even, below 1 = loss.",beispiel:"€18,000 / €15,000 = 1.2 → profit"},hu:{term:"Gazdaságosság",erklaerung:"Árbevétel / költség. 1 felett = nyereség, pontosan 1 = költségfedezet, 1 alatt = veszteség.",beispiel:"18 000 € / 15 000 € = 1,2 → nyereség"}},{de:{term:"Rentabilität",erklaerung:"Gewinn / Kapitaleinsatz · 100. Zeigt, wie hoch sich das eingesetzte Kapital verzinst – je höher, desto erfolgreicher.",beispiel:"500.000 / 6.000.000 · 100 = 8,33 %"},en:{term:"Return on capital",erklaerung:"Profit / capital employed · 100. Shows the rate of return on the capital invested – the higher, the more successful.",beispiel:"500,000 / 6,000,000 · 100 = 8.33%"},hu:{term:"Jövedelmezőség",erklaerung:"Nyereség / befektetett tőke · 100. Megmutatja, milyen mértékben térül meg a befektetett tőke – minél magasabb, annál sikeresebb.",beispiel:"500 000 / 6 000 000 · 100 = 8,33%"}},{de:{term:"Hybride Leistung",erklaerung:"Kombination aus Sachgut und Dienstleistung als gemeinsamer Output.",beispiel:"Neue Software + Schulung der Mitarbeiter:innen"},en:{term:"Hybrid output",erklaerung:"A combination of a physical good and a service as a joint output.",beispiel:"New software + staff training"},hu:{term:"Hibrid teljesítmény",erklaerung:"Tárgyi termék és szolgáltatás kombinációja közös outputként.",beispiel:"Új szoftver + a munkatársak betanítása"}},{de:{term:"Termintreue & Flexibilität",erklaerung:"Termintreue = termingerechte / alle ausgelieferten Aufträge · 100. Flexibilität = erfüllte / angefragte Sonderwünsche · 100.",beispiel:"45 von 50 Aufträgen pünktlich = 90 % Termintreue"},en:{term:"On-time delivery & flexibility",erklaerung:"On-time delivery = orders delivered on time / all orders delivered · 100. Flexibility = special requests met / requested · 100.",beispiel:"45 of 50 orders on time = 90% on-time delivery"},hu:{term:"Határidő-pontosság és rugalmasság",erklaerung:"Határidő-pontosság = időben teljesített / összes kiszállított megrendelés · 100. Rugalmasság = teljesített / kért egyedi kérések · 100.",beispiel:"50 megrendelésből 45 időben = 90% határidő-pontosság"}}],"kunde-im-mittelpunkt":[{de:{term:"Customer Journey",erklaerung:"Der „Weg“ der Kund:innen mit allen Touchpoints vor dem Kauf (Werbung, Social Media), während des Kaufs (Geschäft, Onlineshop) und nach dem Kauf (Service, Member-Club)."},en:{term:"Customer journey",erklaerung:"The customer's ‘journey’ with all touchpoints before the purchase (ads, social media), during the purchase (shop, online shop) and after the purchase (service, member club)."},hu:{term:"Vásárlói út (customer journey)",erklaerung:"A vevő „útja” az összes érintkezési ponttal a vásárlás előtt (reklám, közösségi média), közben (üzlet, webáruház) és után (ügyfélszolgálat, tagsági klub)."}},{de:{term:"STP-Modell",erklaerung:"Segmenting (Markt in Teilmärkte aufteilen) → Targeting (Zielmarkt auswählen) → Positioning (mit bedeutsamem Nutzen überzeugen)."},en:{term:"STP model",erklaerung:"Segmenting (divide the market into sub-markets) → Targeting (choose the target market) → Positioning (convince with a meaningful benefit)."},hu:{term:"STP-modell",erklaerung:"Szegmentálás (a piac felosztása részpiacokra) → célpiac kiválasztása (targeting) → pozicionálás (meggyőzés jelentős előnnyel)."}},{de:{term:"Marktpsychologische vs. marktökonomische Ziele",erklaerung:"Marktpsychologisch: Zufriedenheit, Bekanntheit, Image, Markentreue (schwer messbar). Marktökonomisch: Absatz, Umsatz, Marktanteil, Wachstum (gut messbar)."},en:{term:"Market-psychological vs. market-economic goals",erklaerung:"Market-psychological: satisfaction, awareness, image, brand loyalty (hard to measure). Market-economic: sales volume, revenue, market share, growth (easy to measure)."},hu:{term:"Piaclélektani és piacgazdasági célok",erklaerung:"Piaclélektani: elégedettség, ismertség, imázs, márkahűség (nehezen mérhető). Piacgazdasági: értékesített mennyiség, árbevétel, piaci részesedés, növekedés (jól mérhető)."}},{de:{term:"Segmentierungskriterien",erklaerung:"Geografisch (Länder, Städte), demografisch (Alter, Einkommen), psychografisch (Lebensstil, Werte), verhaltensbezogen (Markentreue, Kaufverhalten)."},en:{term:"Segmentation criteria",erklaerung:"Geographic (countries, cities), demographic (age, income), psychographic (lifestyle, values), behavioural (brand loyalty, buying behaviour)."},hu:{term:"Szegmentálási ismérvek",erklaerung:"Földrajzi (országok, városok), demográfiai (életkor, jövedelem), pszichográfiai (életstílus, értékek), magatartási (márkahűség, vásárlási szokások)."}},{de:{term:"Marktbearbeitungsstrategien",erklaerung:"Konzentriert: ein oder mehrere Segmente gezielt. Differenziert: alle Segmente, jeweils unterschiedlich. Undifferenziert: ein Angebot für den Gesamtmarkt.",beispiel:"Nur Herren-Sneaker · Sneaker für Herren, Damen, Kinder · ein Modell für alle"},en:{term:"Market coverage strategies",erklaerung:"Concentrated: one or more segments deliberately. Differentiated: all segments, each served differently. Undifferentiated: one offer for the whole market.",beispiel:"Men's sneakers only · sneakers for men, women, children · one model for all"},hu:{term:"Piacfeldolgozási stratégiák",erklaerung:"Koncentrált: egy vagy több szegmens célzottan. Differenciált: minden szegmens, eltérő módon. Differenciálatlan: egyetlen ajánlat a teljes piacnak.",beispiel:"Csak férfi sneaker · sneaker férfiaknak, nőknek, gyerekeknek · egy modell mindenkinek"}}],marktforschung:[{de:{term:"Sekundäre Marktforschung (Desk Research)",erklaerung:"Auswertung bereits vorhandener Daten – intern (Umsatz-, Kundenstatistiken) oder extern (Internet, amtliche Statistik). Günstig, aber nicht genau auf die Frage zugeschnitten."},en:{term:"Secondary market research (desk research)",erklaerung:"Analysis of existing data – internal (sales, customer statistics) or external (internet, official statistics). Cheap, but not tailored exactly to the question."},hu:{term:"Szekunder piackutatás (desk research)",erklaerung:"Már meglévő adatok elemzése – belső (értékesítési, vevőstatisztikák) vagy külső (internet, hivatalos statisztika). Olcsó, de nem pontosan a kérdésre szabott."}},{de:{term:"Primäre Marktforschung (Field Research)",erklaerung:"Neue Daten werden direkt am Markt erhoben: Befragung, Beobachtung, Experiment, Panel. Teurer, aber genau passend."},en:{term:"Primary market research (field research)",erklaerung:"New data are collected directly in the market: survey, observation, experiment, panel. More expensive, but an exact fit."},hu:{term:"Primer piackutatás (field research)",erklaerung:"Új adatok gyűjtése közvetlenül a piacon: megkérdezés, megfigyelés, kísérlet, panel. Drágább, de pontosan illeszkedik."}},{de:{term:"Grundgesamtheit & Stichprobe",erklaerung:"Grundgesamtheit = alle Personen der untersuchten Gruppe (Vollerhebung). Stichprobe = repräsentativer Teil davon (Teilerhebung).",beispiel:"400 von 50.000 Passagieren werden befragt"},en:{term:"Population & sample",erklaerung:"Population = all members of the group studied (full survey). Sample = a representative part of it (partial survey).",beispiel:"400 out of 50,000 passengers are surveyed"},hu:{term:"Alapsokaság és minta",erklaerung:"Alapsokaság = a vizsgált csoport összes tagja (teljes körű felmérés). Minta = annak reprezentatív része (részleges felmérés).",beispiel:"50 000 utasból 400-at kérdeznek meg"}},{de:{term:"Panelerhebung",erklaerung:"Dieselbe Personengruppe wird regelmäßig zum selben Thema befragt oder beobachtet – so erkennt man Veränderungen und Trends.",beispiel:"2.000 Haushalte melden jeden Monat ihre Einkäufe"},en:{term:"Panel survey",erklaerung:"The same group of people is surveyed or observed regularly on the same topic – this reveals changes and trends.",beispiel:"2,000 households report their purchases every month"},hu:{term:"Panelfelmérés",erklaerung:"Ugyanazt a személycsoportot rendszeresen kérdezik meg vagy figyelik meg ugyanarról a témáról – így felismerhetők a változások és trendek.",beispiel:"2000 háztartás havonta jelenti a vásárlásait"}},{de:{term:"Feld- vs. Laborbeobachtung",erklaerung:"Feldbeobachtung: in natürlicher Umgebung. Laborbeobachtung: unter kontrollierten Bedingungen.",beispiel:"Kund:innen im umgebauten Supermarkt · Testpersonen im Raum mit neuer Verpackung"},en:{term:"Field vs. laboratory observation",erklaerung:"Field observation: in a natural environment. Laboratory observation: under controlled conditions.",beispiel:"Customers in the redesigned supermarket · test persons in a room with new packaging"},hu:{term:"Terepi és laboratóriumi megfigyelés",erklaerung:"Terepi megfigyelés: természetes környezetben. Laboratóriumi megfigyelés: ellenőrzött körülmények között.",beispiel:"Vásárlók az átrendezett szupermarketben · tesztalanyok egy teremben az új csomagolással"}},{de:{term:"Produkttest, Storetest, Markttest",erklaerung:"Produkttest: Testpersonen probieren das Produkt. Storetest: Verkauf in ausgewählten Geschäften. Markttest: Produkt + Marketing vor der Einführung auf einem Testmarkt."},en:{term:"Product test, store test, test market",erklaerung:"Product test: test persons try the product. Store test: sales in selected shops. Test market: product + marketing in a test market before launch."},hu:{term:"Termékteszt, bolti teszt, piacteszt",erklaerung:"Termékteszt: tesztalanyok kipróbálják a terméket. Bolti teszt: értékesítés kiválasztott üzletekben. Piacteszt: termék + marketing egy tesztpiacon a bevezetés előtt."}},{de:{term:"Offene, geschlossene & skalierte Fragen",erklaerung:"Offen: Antwort in eigenen Worten (neue Erkenntnisse). Geschlossen: Antworten vorgegeben (zählbar). Skaliert: Wahl auf einer Skala (1–6, Smileys)."},en:{term:"Open, closed & scaled questions",erklaerung:"Open: answer in one's own words (new insights). Closed: answers given (countable). Scaled: choice on a scale (1–6, smileys)."},hu:{term:"Nyitott, zárt és skálás kérdések",erklaerung:"Nyitott: válasz saját szavakkal (új felismerések). Zárt: megadott válaszok (megszámlálható). Skálás: választás egy skálán (1–6, smiley-k)."}}]},t={"instrumente-marketings":[{de:{term:"Kundennutzen: Grundnutzen – Zusatznutzen – Zusatzleistung",erklaerung:"Grundnutzen = Hauptzweck des Produkts, Zusatznutzen = Extras (Design, Image), Zusatzleistung = Service (Garantie). Abheben von der Konkurrenz (USP) gelingt meist über Zusatznutzen und -leistung.",beispiel:"iPhone: telefonieren – Kamera und Design – Garantie und Apple-Store-Service"},en:{term:"Customer benefit: core benefit – additional benefit – additional service",erklaerung:"Core benefit = main purpose of the product, additional benefit = extras (design, image), additional service = service (warranty). Standing out (USP) usually works via the extras and services.",beispiel:"iPhone: making calls – camera and design – warranty and Apple Store service"},hu:{term:"Vevői érték: alaphaszon – kiegészítő haszon – kiegészítő szolgáltatás",erklaerung:"Alaphaszon = a termék fő rendeltetése, kiegészítő haszon = extrák (dizájn, imázs), kiegészítő szolgáltatás = szerviz (garancia). A versenytársaktól (USP) főleg az utóbbi kettővel lehet kitűnni.",beispiel:"iPhone: telefonálás – kamera és dizájn – garancia és Apple Store szerviz"}},{de:{term:"Relativer Marktanteil",erklaerung:"Eigener Marktanteil : Marktanteil des größten Konkurrenten. Ein Wert über 1 bedeutet Marktführerschaft. Er ist eine Achse der BCG-Matrix.",beispiel:"12 % : 30 % = 0,4 → niedriger relativer Marktanteil"},en:{term:"Relative market share",erklaerung:"Own market share ÷ market share of the biggest competitor. A value above 1 means market leadership. It is one axis of the BCG matrix.",beispiel:"12 % ÷ 30 % = 0.4 → low relative market share"},hu:{term:"Relatív piaci részesedés",erklaerung:"Saját piaci részesedés : a legnagyobb versenytárs piaci részesedése. Az 1 feletti érték piacvezető szerepet jelent. A BCG-mátrix egyik tengelye.",beispiel:"12 % : 30 % = 0,4 → alacsony relatív piaci részesedés"}},{de:{term:"Tausend-Kontakt-Preis (TKP)",erklaerung:"Werbekosten · 1.000 / Zahl der erreichten Personen. Zeigt, was es kostet, 1.000 Personen zu erreichen – damit lassen sich Werbeträger vergleichen.",beispiel:"500 € · 1.000 / 50.000 = 10 € pro 1.000 Kontakte"},en:{term:"Cost per thousand (CPM)",erklaerung:"Advertising costs · 1,000 / number of people reached. Shows what it costs to reach 1,000 people – useful for comparing advertising media.",beispiel:"€500 · 1,000 / 50,000 = €10 per 1,000 contacts"},hu:{term:"Ezer kontaktusra jutó ár (TKP)",erklaerung:"Reklámköltség · 1000 / az elért személyek száma. Megmutatja, mennyibe kerül 1000 ember elérése – így összevethetők a reklámhordozók.",beispiel:"500 € · 1000 / 50 000 = 10 € ezer kontaktusonként"}},{de:{term:"AIDAS-Formel",erklaerung:"Stufen wirksamer Werbung: Attention (Aufmerksamkeit), Interest (Interesse), Desire (Kaufwunsch), Action (Kauf), Satisfaction (Zufriedenheit nach dem Kauf).",beispiel:"Auffälliges Plakat → Infos zum neuen Bonbon → Lust darauf → Kauf → zufriedene Stammkundin"},en:{term:"AIDAS formula",erklaerung:"Stages of effective advertising: Attention, Interest, Desire, Action (purchase), Satisfaction (after the purchase).",beispiel:"Eye-catching poster → info on the new sweet → craving → purchase → satisfied regular customer"},hu:{term:"AIDAS-modell",erklaerung:"A hatékony reklám lépései: Attention (figyelemfelkeltés), Interest (érdeklődés), Desire (vásárlási vágy), Action (vásárlás), Satisfaction (vásárlás utáni elégedettség).",beispiel:"Feltűnő plakát → infó az új cukorkáról → kedvet kap → vásárlás → elégedett törzsvevő"}},{de:{term:"Abschöpfung vs. Marktdurchdringung",erklaerung:"Abschöpfung: mit hohem Preis starten und später senken. Marktdurchdringung: mit niedrigem Preis starten, schnell Kund:innen gewinnen und später erhöhen.",beispiel:"PS5 (Abschöpfung) · Netflix (Marktdurchdringung)"},en:{term:"Skimming vs. penetration pricing",erklaerung:"Skimming: start with a high price and lower it later. Penetration: start with a low price, win customers quickly and raise it later.",beispiel:"PS5 (skimming) · Netflix (penetration)"},hu:{term:"Lefölözés vs. piacpenetráció",erklaerung:"Lefölözés: magas árral indulni, később csökkenteni. Piacpenetráció: alacsony árral indulni, gyorsan vevőket szerezni, később emelni.",beispiel:"PS5 (lefölözés) · Netflix (piacpenetráció)"}}],"material-warenwirtschaft":[{de:{term:"Rohstoffe",erklaerung:"Stoffe, die als Hauptbestandteil in das Produkt eingehen.",beispiel:"Holz beim Tisch, Kakao bei Pralinen"},en:{term:"Raw materials",erklaerung:"Materials that become a main component of the product.",beispiel:"Wood in a table, cocoa in chocolates"},hu:{term:"Alapanyagok (nyersanyagok)",erklaerung:"Olyan anyagok, amelyek a termék fő alkotórészeként épülnek be.",beispiel:"Fa az asztalban, kakaó a bonbonban"}},{de:{term:"Hilfsstoffe",erklaerung:"Stoffe, die als Nebenbestandteil in das Produkt eingehen.",beispiel:"Leim und Schrauben beim Tisch"},en:{term:"Auxiliary materials",erklaerung:"Materials that become a minor component of the product.",beispiel:"Glue and screws in a table"},hu:{term:"Segédanyagok",erklaerung:"Olyan anyagok, amelyek a termék mellékes alkotórészeként épülnek be.",beispiel:"Ragasztó és csavarok az asztalban"}},{de:{term:"Betriebsstoffe",erklaerung:"Stoffe, die bei der Produktion verbraucht werden, aber nicht in das Produkt eingehen.",beispiel:"Strom, Schmieröl, Reinigungsmittel"},en:{term:"Operating supplies",erklaerung:"Materials that are used up in production but do not become part of the product.",beispiel:"Electricity, lubricating oil, cleaning agents"},hu:{term:"Üzemi anyagok",erklaerung:"A termelés során elhasználódó anyagok, amelyek nem épülnek be a termékbe.",beispiel:"Áram, kenőolaj, tisztítószer"}},{de:{term:"Handelswaren",erklaerung:"Güter, die eingekauft und ohne wesentliche Bearbeitung an Kund:innen weiterverkauft werden.",beispiel:"Loopy kauft fertige Kaugummis und verkauft sie unverändert"},en:{term:"Merchandise (goods for resale)",erklaerung:"Goods that are bought and resold to customers without substantial processing.",beispiel:"Loopy buys ready-made chewing gum and sells it unchanged"},hu:{term:"Kereskedelmi áruk",erklaerung:"Olyan javak, amelyeket megvásárolnak, és lényeges feldolgozás nélkül adnak tovább a vevőknek.",beispiel:"Loopy kész rágógumit vesz, és változatlanul eladja"}},{de:{term:"Materialwirtschaft vs. Warenwirtschaft",erklaerung:"Materialwirtschaft: v. a. Produktionsbetriebe, beschafft Roh-, Hilfs- und Betriebsstoffe. Warenwirtschaft: v. a. Handelsbetriebe, beschafft Handelswaren.",beispiel:"Tischlerei (Material) · Supermarkt (Waren)"},en:{term:"Materials management vs. merchandise management",erklaerung:"Materials management: mainly manufacturers, procures raw and auxiliary materials and operating supplies. Merchandise management: mainly traders, procures goods for resale.",beispiel:"Joinery (materials) · supermarket (merchandise)"},hu:{term:"Anyaggazdálkodás vs. árugazdálkodás",erklaerung:"Anyaggazdálkodás: főleg termelő vállalatok, alap-, segéd- és üzemi anyagokat szerez be. Árugazdálkodás: főleg kereskedők, kereskedelmi árut szerez be.",beispiel:"Asztalosműhely (anyag) · szupermarket (áru)"}},{de:{term:"Bereitstellung: Qualität – Menge – Zeit – Ort",erklaerung:"Die Material- und Warenwirtschaft stellt Güter in der erforderlichen Qualität, der richtigen Menge, zum richtigen Zeitpunkt und am richtigen Ort bereit – möglichst kostengünstig.",beispiel:"Frisches Mehl, 200 kg, Montag 6 Uhr, Filiale Wels"},en:{term:"Provision: quality – quantity – time – place",erklaerung:"Materials and merchandise management provides goods in the required quality, the right quantity, at the right time and in the right place – as cheaply as possible.",beispiel:"Fresh flour, 200 kg, Monday 6 a.m., Wels branch"},hu:{term:"Rendelkezésre bocsátás: minőség – mennyiség – idő – hely",erklaerung:"Az anyag- és árugazdálkodás a javakat megfelelő minőségben és mennyiségben, a megfelelő időben és helyen biztosítja – a lehető legkisebb költséggel.",beispiel:"Friss liszt, 200 kg, hétfő reggel 6, welsi fióküzlet"}},{de:{term:"Bereiche der Material- und Warenwirtschaft",erklaerung:"Beschaffung (Beschaffungsmarketing) → Lagerung (Lagerlogistik) → Verteilung (Transportlogistik) → Entsorgung (Entsorgungslogistik).",beispiel:"Kakao einkaufen → lagern → in die Filialen liefern → Verpackung entsorgen"},en:{term:"Areas of materials and merchandise management",erklaerung:"Procurement (procurement marketing) → storage (warehouse logistics) → distribution (transport logistics) → disposal (disposal logistics).",beispiel:"Buy cocoa → store it → deliver to branches → dispose of packaging"},hu:{term:"Az anyag- és árugazdálkodás területei",erklaerung:"Beszerzés (beszerzési marketing) → raktározás (raktárlogisztika) → elosztás (szállítási logisztika) → hulladékkezelés (hulladéklogisztika).",beispiel:"Kakaó vásárlása → tárolás → szállítás a fióküzletekbe → csomagolás elszállítása"}}],beschaffungsmarketing:[{de:{term:"Beschaffungsprinzipien",erklaerung:"Vorratsbeschaffung (große Mengen lagern), Just-in-time (Lieferung genau bei Bedarf), Einzelbeschaffung (erst bei Auftrag bestellen). Meist werden alle drei je nach Gut kombiniert.",beispiel:"Zucker auf Vorrat · Verpackung just in time · Spezialschokolade auf Auftrag"},en:{term:"Procurement principles",erklaerung:"Procurement for stock (store large quantities), just-in-time (delivery exactly when needed), individual procurement (order only when there is a customer order). Usually all three are combined.",beispiel:"Sugar for stock · packaging just in time · special chocolate per order"},hu:{term:"Beszerzési elvek",erklaerung:"Készletre történő beszerzés (nagy mennyiség tárolása), just-in-time (szállítás pontosan igény esetén), egyedi beszerzés (csak megrendelésre). Általában mindhármat kombinálják.",beispiel:"Cukor készletre · csomagolás just-in-time · különleges csokoládé megrendelésre"}},{de:{term:"Nettobedarf",erklaerung:"Bruttobedarf (Materialbedarf laut Stückliste · Produktionsmenge) − Lagerbestand = Nettobedarf, also die Menge, die tatsächlich beschafft werden muss.",beispiel:"0,15 kg · 1.200 = 180 kg − 40 kg Lager = 140 kg"},en:{term:"Net requirement",erklaerung:"Gross requirement (material per bill of materials · production quantity) − stock = net requirement, i.e. the quantity that actually has to be procured.",beispiel:"0.15 kg · 1,200 = 180 kg − 40 kg in stock = 140 kg"},hu:{term:"Nettó szükséglet",erklaerung:"Bruttó szükséglet (anyagszükséglet a darabjegyzék szerint · gyártási mennyiség) − raktárkészlet = nettó szükséglet, vagyis a ténylegesen beszerzendő mennyiség.",beispiel:"0,15 kg · 1200 = 180 kg − 40 kg készlet = 140 kg"}},{de:{term:"Zentrale vs. dezentrale Beschaffung",erklaerung:"Zentral (eine Stelle): günstige Konditionen durch große Mengen, gute Kontrolle, aber mehr Verwaltung und wenig flexibel. Dezentral (mehrere Stellen): flexibler, Ware schneller vor Ort.",beispiel:"Supermarktkette kauft zentral · Filiale kauft Brot regional"},en:{term:"Centralised vs. decentralised procurement",erklaerung:"Centralised (one unit): good terms through large quantities, good control, but more admin and less flexible. Decentralised (several units): more flexible, goods on site faster.",beispiel:"Supermarket chain buys centrally · branch buys bread locally"},hu:{term:"Központosított vs. decentralizált beszerzés",erklaerung:"Központosított (egy egység): nagy mennyiség miatt kedvező feltételek, jó ellenőrzés, de több adminisztráció, kevésbé rugalmas. Decentralizált (több egység): rugalmasabb, gyorsabban helyben az áru.",beispiel:"Szupermarketlánc központilag vásárol · fióküzlet helyben veszi a kenyeret"}},{de:{term:"Lagerhaltungskostensatz",erklaerung:"Zinssatz + Lagerkostensatz. Steht in der Formel der optimalen Bestellmenge im Nenner: Je höher er ist, desto kleiner die optimale Bestellmenge.",beispiel:"6 % Zinsen + 10 % Lagerkosten = 16 %"},en:{term:"Holding cost rate",erklaerung:"Interest rate + storage cost rate. It is in the denominator of the optimal order quantity formula: the higher it is, the smaller the optimal order quantity.",beispiel:"6 % interest + 10 % storage costs = 16 %"},hu:{term:"Készlettartási költségráta",erklaerung:"Kamatláb + raktározási költségráta. Az optimális rendelési mennyiség képletének nevezőjében áll: minél magasabb, annál kisebb az optimális rendelési mennyiség.",beispiel:"6 % kamat + 10 % raktározási költség = 16 %"}}],"lager-transport-entsorgung":[{de:{term:"Funktionen des Lagers",erklaerung:"Umformung (Reifung), Sicherung (Reserve), Spekulation (vor Preisanstieg kaufen), Ausgleich (Zeit überbrücken), Warenpräsentation (Lager = Verkaufsraum), Entsorgung (Reste sammeln).",beispiel:"Käse reift · Reservevorrat · IKEA-Halle"},en:{term:"Functions of a warehouse",erklaerung:"Transformation (maturing), safety (reserve), speculation (buying before prices rise), balancing (bridging time), presentation (warehouse = salesroom), disposal (collecting leftovers).",beispiel:"Cheese matures · reserve stock · IKEA hall"},hu:{term:"A raktározás funkciói",erklaerung:"Átalakító (érlelés), biztonsági (tartalék), spekulációs (vásárlás áremelkedés előtt), kiegyenlítő (időáthidalás), árubemutató (raktár = eladótér), hulladékkezelési (maradékok gyűjtése).",beispiel:"Sajt érlelése · tartalékkészlet · IKEA-csarnok"}},{de:{term:"Offenes – halboffenes – geschlossenes Lager",erklaerung:"Offen: wetterunempfindliche, nicht diebstahlgefährdete Waren. Halboffen: befestigte Fläche mit Zaun/Dach. Geschlossen: Gebäude für wetterempfindliche, diebstahlgefährdete Waren.",beispiel:"Sand · Holzbretter · Elektronik"},en:{term:"Open – semi-open – closed warehouse",erklaerung:"Open: weatherproof goods not at risk of theft. Semi-open: paved area with fence/roof. Closed: building for weather-sensitive goods at risk of theft.",beispiel:"Sand · wooden boards · electronics"},hu:{term:"Nyitott – félig nyitott – zárt raktár",erklaerung:"Nyitott: időjárásálló, lopásnak nem kitett áruk. Félig nyitott: burkolt terület kerítéssel/tetővel. Zárt: épület az időjárásra érzékeny, lopásveszélyes áruknak.",beispiel:"Homok · deszkák · elektronika"}},{de:{term:"Festplatzsystem vs. Freiplatzsystem",erklaerung:"Festplatz: jede Ware hat einen fixen Platz (Platz für die höchste Menge nötig). Freiplatz (chaotisch): Ware kommt dorthin, wo Platz frei ist – optimale Platznutzung, braucht EDV, nicht für Gefahrengüter.",beispiel:"Amazon arbeitet chaotisch"},en:{term:"Fixed-location vs. free-location system",erklaerung:"Fixed location: each item has a fixed place (space for the largest quantity needed). Free location (chaotic): goods go wherever space is free – optimal use of space, needs IT, not for hazardous goods.",beispiel:"Amazon uses chaotic storage"},hu:{term:"Fix helyes vs. szabad helyes tárolás",erklaerung:"Fix helyes: minden árunak állandó helye van (a legnagyobb mennyiségnek kell hely). Szabad helyes (kaotikus): oda kerül, ahol hely van – optimális helykihasználás, informatikát igényel, veszélyes árura nem alkalmas.",beispiel:"Az Amazon kaotikus raktárt használ"}},{de:{term:"Ø Lagerbestand",erklaerung:"(Anfangsbestand + Endbestand) / 2. Grundlage für Umschlagshäufigkeit und Lagerkosten in %.",beispiel:"(20.000 + 25.000) / 2 = 22.500 €"},en:{term:"Average stock",erklaerung:"(Opening stock + closing stock) / 2. Basis for the turnover rate and storage costs in %.",beispiel:"(20,000 + 25,000) / 2 = €22,500"},hu:{term:"Átlagos készlet",erklaerung:"(Nyitókészlet + zárókészlet) / 2. Ebből számítjuk a forgási sebességet és a raktározási költség %-át.",beispiel:"(20 000 + 25 000) / 2 = 22 500 €"}},{de:{term:"Lagerumschlagshäufigkeit",erklaerung:"Wareneinsatz / Ø Lagerbestand. Zeigt, wie oft das Lager pro Jahr umgeschlagen wird – soll HOCH sein. Wareneinsatz = Einstandspreis · Verkäufe.",beispiel:"60.000 / 12.000 = 5-mal pro Jahr"},en:{term:"Stock turnover rate",erklaerung:"Cost of goods sold / average stock. Shows how often stock is turned over per year – should be HIGH. Cost of goods sold = purchase price · units sold.",beispiel:"60,000 / 12,000 = 5 times a year"},hu:{term:"Készletforgási sebesség",erklaerung:"Eladott áruk beszerzési értéke / átlagkészlet. Megmutatja, évente hányszor fordul meg a készlet – legyen MAGAS. Eladott áruk értéke = beszerzési ár · eladott mennyiség.",beispiel:"60 000 / 12 000 = évente 5-ször"}},{de:{term:"Lagerumschlagsdauer",erklaerung:"365 / Lagerumschlagshäufigkeit. Zeigt, wie viele Tage die Ware durchschnittlich im Lager liegt – soll GERING sein.",beispiel:"365 / 5 = 73 Tage"},en:{term:"Average storage period",erklaerung:"365 / stock turnover rate. Shows how many days goods stay in stock on average – should be SHORT.",beispiel:"365 / 5 = 73 days"},hu:{term:"Készletforgási idő (átlagos tárolási idő)",erklaerung:"365 / készletforgási sebesség. Megmutatja, átlagosan hány napig van az áru raktáron – legyen RÖVID.",beispiel:"365 / 5 = 73 nap"}},{de:{term:"Lagerkosten in %",erklaerung:"Lagerkosten / Ø Lagerbestand · 100. Zeigt, wie viel die Lagerung im Verhältnis zum gelagerten Wert kostet.",beispiel:"3.600 / 24.000 · 100 = 15 %"},en:{term:"Storage costs in %",erklaerung:"Storage costs / average stock · 100. Shows how much storage costs in relation to the value stored.",beispiel:"3,600 / 24,000 · 100 = 15 %"},hu:{term:"Raktározási költség %-ban",erklaerung:"Raktározási költség / átlagkészlet · 100. Megmutatja, mennyibe kerül a tárolás a tárolt értékhez képest.",beispiel:"3600 / 24 000 · 100 = 15 %"}},{de:{term:"Abfallhierarchie",erklaerung:"Rangfolge im Umgang mit Abfall: Vermeidung → Vorbereitung zur Wiederverwendung → Recycling → sonstige Verwertung (z. B. Energie) → Beseitigung (nur als letzte Möglichkeit).",beispiel:"Mehrwegkiste statt Karton = Vermeidung"},en:{term:"Waste hierarchy",erklaerung:"Order of priority for dealing with waste: prevention → preparing for reuse → recycling → other recovery (e.g. energy) → disposal (only as a last resort).",beispiel:"Reusable crate instead of a carton = prevention"},hu:{term:"Hulladékhierarchia",erklaerung:"A hulladékkezelés sorrendje: megelőzés → újrahasználatra való előkészítés → újrafeldolgozás → egyéb hasznosítás (pl. energetikai) → ártalmatlanítás (csak végső esetben).",beispiel:"Többutas láda karton helyett = megelőzés"}}],"supply-chain-management":[{de:{term:"Stufen der Supply Chain",erklaerung:"Vorlieferant → Lieferant → Hersteller → Handel → Endverbraucher:in; am Ende kommt noch der Entsorger.",beispiel:"Kakaobauer → Kuvertürehersteller → Pralinenmanufaktur → Loopys Candy Store → Kund:in"},en:{term:"Stages of the supply chain",erklaerung:"Sub-supplier → supplier → manufacturer → retail → end consumer; at the very end comes the disposal company.",beispiel:"Cocoa farmer → couverture producer → chocolate maker → Loopy's Candy Store → customer"},hu:{term:"Az ellátási lánc szintjei",erklaerung:"Előbeszállító → beszállító → gyártó → kereskedelem → végfelhasználó; a legvégén a hulladékkezelő áll.",beispiel:"Kakaótermelő → tortabevonó-gyártó → bonbonmanufaktúra → Loopy édességboltja → vevő"}},{de:{term:"Multi-Sourcing",erklaerung:"Ein Gut wird von mehreren Lieferanten (oft aus verschiedenen Ländern) bezogen statt von einem – fällt einer aus, liefern die anderen weiter.",beispiel:"Apple produziert in China, Indien und Vietnam"},en:{term:"Multi-sourcing",erklaerung:"A good is sourced from several suppliers (often in different countries) instead of one – if one fails, the others keep delivering.",beispiel:"Apple produces in China, India and Vietnam"},hu:{term:"Multi-sourcing (többforrású beszerzés)",erklaerung:"Egy jószágot több beszállítótól (gyakran különböző országokból) szereznek be egy helyett – ha az egyik kiesik, a többiek tovább szállítanak.",beispiel:"Az Apple Kínában, Indiában és Vietnámban gyárt"}},{de:{term:"APS-System",erklaerung:"Supply-Chain-Software (Advanced Planning and Scheduling), die bei Planung und Steuerung der Lieferkette hilft.",beispiel:"Software zeigt sofort, welche Bauteile in zwei Wochen knapp werden"},en:{term:"APS system",erklaerung:"Supply chain software (Advanced Planning and Scheduling) that helps plan and control the supply chain.",beispiel:"Software instantly shows which components will run short in two weeks"},hu:{term:"APS-rendszer",erklaerung:"Ellátásilánc-szoftver (Advanced Planning and Scheduling), amely segít az ellátási lánc tervezésében és irányításában.",beispiel:"A szoftver azonnal jelzi, mely alkatrészekből lesz hiány két hét múlva"}},{de:{term:"Pufferbestand",erklaerung:"Bewusst gehaltene Reserve, die bei Störungen die Versorgung sichert. Kostet Geld (Lager, Kapitalbindung) – Teil des Resilienz-Effizienz-Dilemmas.",beispiel:"Autozulieferer hält drei Wochen Vorrat an Chips"},en:{term:"Buffer stock",erklaerung:"A deliberately held reserve that secures supply during disruptions. It costs money (storage, capital tie-up) – part of the resilience-efficiency dilemma.",beispiel:"Car supplier keeps three weeks' stock of chips"},hu:{term:"Pufferkészlet",erklaerung:"Tudatosan tartott tartalék, amely zavarok esetén biztosítja az ellátást. Pénzbe kerül (raktár, tőkelekötés) – a reziliencia–hatékonyság dilemma része.",beispiel:"Az autóipari beszállító háromheti chipkészletet tart"}},{de:{term:"EU-Lieferkettengesetz (2024)",erklaerung:"EU-Unternehmen dürfen nicht mit Lieferanten zusammenarbeiten, die Kinder- oder Zwangsarbeit einsetzen – Verantwortung für die ganze Lieferkette.",beispiel:"Textilfirma prüft die Nähereien ihrer Lieferanten"},en:{term:"EU Supply Chain Act (2024)",erklaerung:"EU companies may not work with suppliers who use child or forced labour – responsibility for the whole supply chain.",beispiel:"A textile company checks its suppliers' sewing factories"},hu:{term:"Uniós ellátásilánc-irányelv (2024)",erklaerung:"Az EU-s vállalatok nem dolgozhatnak gyermek- vagy kényszermunkát alkalmazó beszállítókkal – felelősség a teljes ellátási láncért.",beispiel:"Egy textilcég ellenőrzi beszállítói varrodáit"}}],logistik:[{de:{term:"Spediteur",erklaerung:"Organisiert Gütertransporte im eigenen Namen für fremde Rechnung und beauftragt dafür Frachtführer. Rechte: Speditionsprovision, Pfandrecht, Selbsteintrittsrecht.",beispiel:"LKW WALTER, DB Schenker"},en:{term:"Freight forwarder",erklaerung:"Organises freight transport in its own name on behalf of others and hires carriers for it. Rights: forwarding commission, lien, right of self-entry.",beispiel:"LKW WALTER, DB Schenker"},hu:{term:"Szállítmányozó",erklaerung:"Saját nevében, más számlájára szervezi az áruszállítást, és ehhez fuvarozókat bíz meg. Jogai: szállítmányozói jutalék, zálogjog, önbelépési jog.",beispiel:"LKW WALTER, DB Schenker"}},{de:{term:"Frachtführer",erklaerung:"Führt den Transport tatsächlich durch. Pflichten: Beförderung, Sorgfalt, Haftung bei Verschulden. Rechte: Fracht (Entgelt), Pfandrecht.",beispiel:"Transportunternehmen mit eigenen Lkw"},en:{term:"Carrier",erklaerung:"Actually carries out the transport. Duties: carriage, due care, liability for fault. Rights: freight charge, lien.",beispiel:"Haulage company with its own trucks"},hu:{term:"Fuvarozó",erklaerung:"Ténylegesen elvégzi a szállítást. Kötelességei: fuvarozás, gondosság, felelősség vétkesség esetén. Jogai: fuvardíj, zálogjog.",beispiel:"Saját kamionokkal rendelkező fuvarozó cég"}},{de:{term:"Speditionsvertrag vs. Frachtvertrag",erklaerung:"Speditionsvertrag: Auftraggeber ↔ Spediteur. Frachtvertrag: Spediteur ↔ Frachtführer. Zwischen Auftraggeber und Frachtführer besteht kein direkter Vertrag.",beispiel:"Möbelhersteller → Spediteur → Frachtführer"},en:{term:"Forwarding contract vs. contract of carriage",erklaerung:"Forwarding contract: client ↔ forwarder. Contract of carriage: forwarder ↔ carrier. There is no direct contract between client and carrier.",beispiel:"Furniture maker → forwarder → carrier"},hu:{term:"Szállítmányozási vs. fuvarozási szerződés",erklaerung:"Szállítmányozási szerződés: megbízó ↔ szállítmányozó. Fuvarozási szerződés: szállítmányozó ↔ fuvarozó. A megbízó és a fuvarozó között nincs közvetlen szerződés.",beispiel:"Bútorgyártó → szállítmányozó → fuvarozó"}},{de:{term:"Selbsteintrittsrecht",erklaerung:"Recht des Spediteurs, den Transport selbst durchzuführen; er hat dann zusätzlich die Rechte und Pflichten eines Frachtführers.",beispiel:"Spediteur fährt die Ladung mit eigenem Lkw nach Mailand"},en:{term:"Right of self-entry",erklaerung:"The forwarder's right to carry out the transport itself; it then also has the rights and duties of a carrier.",beispiel:"The forwarder drives the load to Milan in its own truck"},hu:{term:"Önbelépési jog",erklaerung:"A szállítmányozó joga, hogy maga végezze el a fuvart; ekkor a fuvarozó jogai és kötelességei is megilletik.",beispiel:"A szállítmányozó saját kamionjával viszi a rakományt Milánóba"}},{de:{term:"Frachtbrief",erklaerung:"Beweisurkunde, dass die Ware versendet wurde – kein Wertpapier. Straße: CMR, Bahn: CIM, Luft: Air Waybill.",beispiel:"CMR-Frachtbrief für einen Lkw-Transport nach Deutschland"},en:{term:"Consignment note",erklaerung:"Document proving that the goods were dispatched – not a security. Road: CMR, rail: CIM, air: air waybill.",beispiel:"CMR note for a truck transport to Germany"},hu:{term:"Fuvarlevél",erklaerung:"Okirat, amely igazolja az áru feladását – nem értékpapír. Közút: CMR, vasút: CIM, légi út: Air Waybill.",beispiel:"CMR-fuvarlevél egy Németországba tartó kamionos szállításhoz"}},{de:{term:"Traditionspapier",erklaerung:"Wertpapier, das das Recht an der Ware verbrieft: Wer es besitzt, kann über die Ware verfügen. See- und Flusskonnossement, FIATA Multimodal (FBL).",beispiel:"Bill of Lading für einen Container nach Shanghai"},en:{term:"Document of title",erklaerung:"A security embodying the right to the goods: whoever holds it can dispose of them. Ocean and inland bill of lading, FIATA multimodal (FBL).",beispiel:"Bill of lading for a container to Shanghai"},hu:{term:"Árut megtestesítő értékpapír",erklaerung:"Az árura vonatkozó jogot megtestesítő értékpapír: aki birtokolja, rendelkezhet az áru felett. Tengeri és belvízi hajóraklevél, FIATA multimodális (FBL).",beispiel:"Hajóraklevél (Bill of Lading) egy sanghaji konténerhez"}},{de:{term:"Huckepackverkehr",erklaerung:"Kombinierter Verkehr, bei dem Lkw oder Sattelauflieger mitfahren: Load-on/Load-off (nur Auflieger), Rollende Landstraße (ganzer Lkw auf die Bahn), Roll-on/Roll-off (Lkw aufs Schiff).",beispiel:"RoLa über den Brenner"},en:{term:"Piggyback transport",erklaerung:"Combined transport where trucks or semi-trailers ride along: load-on/load-off (trailer only), rolling road (whole truck on the train), roll-on/roll-off (truck onto the ship).",beispiel:"Rolling road across the Brenner Pass"},hu:{term:"Ráterheléses (huckepack) fuvarozás",erklaerung:"Kombinált fuvarozás, amelyben kamion vagy félpótkocsi utazik: load-on/load-off (csak pótkocsi), gördülő országút (egész kamion vonaton), roll-on/roll-off (kamion hajón).",beispiel:"Gördülő országút a Brenneren át"}},{de:{term:"Behälterverkehr",erklaerung:"Kombinierter Verkehr mit Containern: Der Container wird zwischen Verkehrsträgern umgeladen, die Ware darin bleibt unberührt.",beispiel:"Überseecontainer vom Schiff in Hamburg auf die Bahn nach Wien"},en:{term:"Container transport",erklaerung:"Combined transport with containers: the container is transferred between modes of transport, the goods inside remain untouched.",beispiel:"Overseas container from ship in Hamburg onto rail to Vienna"},hu:{term:"Konténeres fuvarozás",erklaerung:"Kombinált fuvarozás konténerekkel: a konténert átrakják egyik közlekedési ágról a másikra, a benne lévő áruhoz nem nyúlnak.",beispiel:"Tengerentúli konténer Hamburgban hajóról vasútra Bécs felé"}}],"der-handel":[{de:{term:"Einzelhandel vs. Großhandel",erklaerung:"Entscheidend ist die Art der Abnehmer: Einzelhandel verkauft an Letztverbraucher:innen (Konsument:innen), Großhandel an andere Unternehmen.",beispiel:"Lidl, Thalia (Einzelhandel) · Metro, Schachermayer (Großhandel)"},en:{term:"Retail vs. wholesale",erklaerung:"What matters is the type of buyer: retail sells to end consumers, wholesale sells to other businesses.",beispiel:"Lidl, Thalia (retail) · Metro, Schachermayer (wholesale)"},hu:{term:"Kiskereskedelem vs. nagykereskedelem",erklaerung:"A vevők típusa a döntő: a kiskereskedelem végső fogyasztóknak, a nagykereskedelem más vállalatoknak értékesít.",beispiel:"Lidl, Thalia (kiskereskedelem) · Metro, Schachermayer (nagykereskedelem)"}},{de:{term:"Funktionen des Handels",erklaerung:"Räumliche Überbrückung (Transport), zeitliche Überbrückung (Lagerung), quantitativer Ausgleich (groß einkaufen, klein verkaufen), qualitativer Ausgleich (Sortiment bilden, Qualität prüfen).",beispiel:"Christbaumkugeln im Juni kaufen, ab Oktober verkaufen = zeitlich"},en:{term:"Functions of trade",erklaerung:"Bridging distance (transport), bridging time (storage), quantitative balancing (buy big, sell small), qualitative balancing (assemble a range, check quality).",beispiel:"Buying baubles in June, selling from October = bridging time"},hu:{term:"A kereskedelem funkciói",erklaerung:"Térbeli áthidalás (szállítás), időbeli áthidalás (raktározás), mennyiségi kiegyenlítés (nagyban venni, kicsiben eladni), minőségi kiegyenlítés (választék, minőség-ellenőrzés).",beispiel:"Karácsonyfadísz júniusi vásárlása, októbertől eladás = időbeli"}},{de:{term:"Ambulanter (halbstationärer) Handel",erklaerung:"Einzelhandel ohne festen Standort: Straßen- und Markthandel sowie Direktvertrieb (Vertreter:innen, Home-Partys).",beispiel:"Gemüsestand am Wochenmarkt"},en:{term:"Itinerant (semi-stationary) trade",erklaerung:"Retail without a fixed location: street and market trading as well as direct selling (sales reps, home parties).",beispiel:"Vegetable stall at the weekly market"},hu:{term:"Mozgó (félig helyhez kötött) kereskedelem",erklaerung:"Állandó helyszín nélküli kiskereskedelem: utcai és piaci árusítás, valamint közvetlen értékesítés (ügynökök, házibulik).",beispiel:"Zöldségstand a heti piacon"}},{de:{term:"Cash-and-carry",erklaerung:"Form des Abholgroßhandels: Kund:innen (Unternehmen) bedienen sich selbst, zahlen sofort und transportieren die Ware selbst ab.",beispiel:"Wirtin kauft bei Metro ein"},en:{term:"Cash and carry",erklaerung:"A form of collection wholesale: customers (businesses) serve themselves, pay immediately and transport the goods themselves.",beispiel:"A restaurant owner shops at Metro"},hu:{term:"Cash & carry",erklaerung:"Az átvevő nagykereskedelem egyik formája: a vevők (vállalkozások) maguk szolgálják ki magukat, azonnal fizetnek, és maguk szállítják el az árut.",beispiel:"Egy vendéglős a Metróban vásárol"}},{de:{term:"Rackjobber (Regalgroßhändler)",erklaerung:"Großhändler, der Regalflächen in fremden Geschäften mietet und sie selbst mit seinem Sortiment bestückt.",beispiel:"Tchibo-Regal im Supermarkt"},en:{term:"Rack jobber",erklaerung:"A wholesaler who rents shelf space in other retailers' shops and stocks it with its own range.",beispiel:"Tchibo shelf in a supermarket"},hu:{term:"Polcbérlő nagykereskedő (rackjobber)",erklaerung:"Olyan nagykereskedő, amely más üzletekben bérel polcfelületet, és saját választékával tölti fel.",beispiel:"Tchibo-polc a szupermarketben"}},{de:{term:"Franchising",erklaerung:"Selbstständige Franchisenehmer:innen nutzen gegen Gebühr Konzept, Marke und Know-how des Franchisegebers und tragen das unternehmerische Risiko selbst.",beispiel:"McDonald's-Restaurant in Graz"},en:{term:"Franchising",erklaerung:"Independent franchisees use the franchisor's concept, brand and know-how for a fee and bear the business risk themselves.",beispiel:"McDonald's restaurant in Graz"},hu:{term:"Franchise",erklaerung:"Önálló franchise-átvevők díj ellenében használják a franchise-átadó koncepcióját, márkáját és know-how-ját, a vállalkozói kockázatot pedig maguk viselik.",beispiel:"McDonald's étterem Grazban"}},{de:{term:"Freiwillige Handelskette",erklaerung:"Selbstständige Händler:innen treten unter gemeinsamer Marke auf und erledigen Aufgaben wie Einkauf und Werbung gemeinsam.",beispiel:"SPAR-Kaufmann im Ort"},en:{term:"Voluntary chain",erklaerung:"Independent retailers trade under a common brand and carry out tasks such as purchasing and advertising together.",beispiel:"Local SPAR shopkeeper"},hu:{term:"Önkéntes kereskedelmi lánc",erklaerung:"Önálló kereskedők közös márkanév alatt lépnek fel, és bizonyos feladatokat (beszerzés, reklám) közösen végeznek.",beispiel:"A helyi SPAR-kereskedő"}},{de:{term:"Handelsgenossenschaft",erklaerung:"Kooperation, in der selbstständige Händler:innen als Mitglieder gemeinsam Einkauf und Logistik betreiben.",beispiel:"ADEG, Lagerhaus"},en:{term:"Retail cooperative",erklaerung:"A cooperation in which independent traders, as members, run purchasing and logistics together.",beispiel:"ADEG, Lagerhaus"},hu:{term:"Kereskedelmi szövetkezet",erklaerung:"Olyan együttműködés, amelyben önálló kereskedők tagként közösen végzik a beszerzést és a logisztikát.",beispiel:"ADEG, Lagerhaus"}}],"businessplan-2jg":[{de:{term:"Scoring-Methode (Punktwertmethode)",erklaerung:"Standortfaktoren festlegen und gewichten (zusammen 100 %), Standorte bewerten, Punkte × Gewichtung, addieren – das höchste Ergebnis ist der beste Standort.",beispiel:"B: 5 · 0,6 + 1 · 0,4 = 3,4 schlägt A mit 3,2"},en:{term:"Scoring method (weighted point method)",erklaerung:"Define and weight location factors (100 % in total), rate the locations, multiply points by weight, add up – the highest result is the best location.",beispiel:"B: 5 · 0.6 + 1 · 0.4 = 3.4 beats A with 3.2"},hu:{term:"Pontozásos módszer (súlyozott pontozás)",erklaerung:"Telephelyi tényezők kijelölése és súlyozása (összesen 100 %), a helyszínek értékelése, pont × súly, összeadás – a legmagasabb eredmény a legjobb telephely.",beispiel:"B: 5 · 0,6 + 1 · 0,4 = 3,4 megelőzi A-t (3,2)"}},{de:{term:"SMART-Ziele",erklaerung:"Ziele sollen spezifisch, messbar, attraktiv, realistisch und terminiert sein.",beispiel:"„Bis 31. Dezember 1.000 Instagram-Follower:innen gewinnen“"},en:{term:"SMART goals",erklaerung:"Goals should be specific, measurable, attractive (achievable), realistic and time-bound.",beispiel:"'Gain 1,000 Instagram followers by 31 December'"},hu:{term:"SMART célok",erklaerung:"A célok legyenek konkrétak (specifikusak), mérhetők, vonzók, reálisak és határidőhöz kötöttek.",beispiel:"„December 31-ig 1000 Instagram-követő megszerzése”"}},{de:{term:"Kritischer Pfad",erklaerung:"Kette jener Aktivitäten im Umsetzungsfahrplan, die keinen Zeitpuffer haben – verzögert sich eine davon, verschiebt sich das ganze Projekt.",beispiel:"Gewerbeanmeldung verspätet → Eröffnung verschiebt sich"},en:{term:"Critical path",erklaerung:"The chain of activities in the implementation roadmap that have no time buffer – if one of them is delayed, the whole project is delayed.",beispiel:"Late trade licence registration → opening is postponed"},hu:{term:"Kritikus út",erklaerung:"A megvalósítási ütemterv azon tevékenységeinek lánca, amelyeknek nincs időtartalékuk – ha bármelyik késik, az egész projekt csúszik.",beispiel:"Késik az iparűzési bejelentés → csúszik a nyitás"}},{de:{term:"Direkte vs. indirekte Konkurrenz",erklaerung:"Direkte Konkurrenz: gleiche Branche, gleiches Angebot. Indirekte Konkurrenz: stillt dasselbe Bedürfnis auf andere Weise.",beispiel:"ORF ↔ ProSieben (direkt) · ORF ↔ Streaming (indirekt)"},en:{term:"Direct vs. indirect competition",erklaerung:"Direct competition: same industry, same offer. Indirect competition: satisfies the same need in a different way.",beispiel:"ORF ↔ ProSieben (direct) · ORF ↔ streaming (indirect)"},hu:{term:"Közvetlen vs. közvetett verseny",erklaerung:"Közvetlen verseny: azonos ágazat, azonos kínálat. Közvetett verseny: ugyanazt a szükségletet más módon elégíti ki.",beispiel:"ORF ↔ ProSieben (közvetlen) · ORF ↔ streaming (közvetett)"}},{de:{term:"Schutzrechte",erklaerung:"Registrierungs- und kostenpflichtig: Patent, Gebrauchsmuster (schneller, schwächer), Marke, Design, Herkunftsangaben. Kostenfrei: Urheberrecht, Betriebsgeheimnisse.",beispiel:"Logo als Marke anmelden · Rezept als Betriebsgeheimnis hüten"},en:{term:"Intellectual property rights",erklaerung:"Registered and fee-based: patent, utility model (faster, weaker), trademark, design, geographical indications. Free: copyright, trade secrets.",beispiel:"Register the logo as a trademark · keep the recipe as a trade secret"},hu:{term:"Oltalmi jogok",erklaerung:"Bejegyzéshez kötött, díjköteles: szabadalom, használati minta (gyorsabb, gyengébb), védjegy, formatervezési minta, földrajzi árujelző. Ingyenes: szerzői jog, üzleti titok.",beispiel:"A logó védjegyként való bejegyzése · a recept őrzése üzleti titokként"}}]},n=e(r,t);export{n as default};
